import ApiService from '../services/api';
import { humanizeOrchestrationStage } from '../constants/orchestrationUxLabels';

export type ReportOrchestrationProfile = 'light' | 'standard' | 'full';

export type StagedOrchestrationStageStatus = 'pending' | 'running' | 'completed' | 'failed';

export type StagedOrchestrationStageState = {
  stage: string;
  label: string;
  status: StagedOrchestrationStageStatus;
  error?: string | null;
};

export type StagedReportOrchestrationOptions = {
  period?: string;
  cbamPeriod?: string;
  iso14067Period?: string;
  profile?: ReportOrchestrationProfile;
  runWorkflows?: boolean;
  persistResults?: boolean;
  actionLimit?: number;
  includeBuyerOrchestration?: boolean;
  includeInventoryReview?: boolean;
  runAutopilot?: boolean;
  includeBrsrOrchestration?: boolean;
  includeIsoOrchestration?: boolean;
  includePcfOrchestration?: boolean;
  includeCbamOrchestration?: boolean;
  onStageStart?: (stage: string) => void;
  onStageComplete?: (stage: string, payload: Record<string, unknown>) => void;
};

export type StagedReportOrchestrationResult = {
  success: boolean;
  profile: ReportOrchestrationProfile;
  stages: StagedOrchestrationStageState[];
  partialFailures?: Array<{ type?: string; id?: string; message?: string }>;
  bundle?: {
    summary?: {
      message?: string;
      successCount?: number;
      failedCount?: number;
    };
  };
  message?: string;
};

const PROFILE_STAGES: Record<ReportOrchestrationProfile, string[]> = {
  light: ['workflow_orchestration', 'bundle_assembly'],
  standard: ['statutory_reports', 'supplier_export_reports', 'certification_pack', 'bundle_assembly'],
  full: [
    'workflow_orchestration',
    'statutory_reports',
    'supplier_export_reports',
    'certification_pack',
    'finance_pat_hydrogen_reports',
    'bundle_assembly',
  ],
};

const resolveStagesForProfile = (
  profile: ReportOrchestrationProfile,
  runWorkflows?: boolean
): string[] => {
  let stages = [...PROFILE_STAGES[profile]];
  if (runWorkflows === true && !stages.includes('workflow_orchestration')) {
    stages = ['workflow_orchestration', ...stages.filter((s) => s !== 'workflow_orchestration')];
  }
  if (runWorkflows === false) {
    stages = stages.filter((s) => s !== 'workflow_orchestration');
  }
  return stages;
};

export const buildInitialStagedOrchestrationState = (
  profile: ReportOrchestrationProfile = 'standard',
  runWorkflows?: boolean
): StagedOrchestrationStageState[] =>
  resolveStagesForProfile(profile, runWorkflows).map((stage) => ({
    stage,
    label: humanizeOrchestrationStage(stage),
    status: 'pending',
  }));

export async function runStagedReportOrchestration(
  options: StagedReportOrchestrationOptions = {}
): Promise<StagedReportOrchestrationResult> {
  const profile = options.profile ?? 'standard';
  const stagesToRun = resolveStagesForProfile(profile, options.runWorkflows);
  const stageStates: StagedOrchestrationStageState[] = stagesToRun.map((stage) => ({
    stage,
    label: humanizeOrchestrationStage(stage),
    status: 'pending',
  }));

  let accumulated: Record<string, unknown> = {};
  let lastBundle: StagedReportOrchestrationResult['bundle'];
  let lastMessage: string | undefined;
  let lastPartialFailures: Array<{ type?: string; id?: string; message?: string }> = [];
  let overallSuccess = true;

  for (let index = 0; index < stagesToRun.length; index += 1) {
    const stage = stagesToRun[index];
    stageStates[index] = { ...stageStates[index], status: 'running' };
    options.onStageStart?.(stage);

    try {
      const response = await ApiService.orchestrateReportStage({
        stage,
        period: options.period,
        cbamPeriod: options.cbamPeriod,
        iso14067Period: options.iso14067Period,
        profile: options.profile,
        runWorkflows: options.runWorkflows,
        persistResults: stage === 'bundle_assembly' ? options.persistResults !== false : false,
        actionLimit: options.actionLimit,
        includeBuyerOrchestration: options.includeBuyerOrchestration,
        includeInventoryReview: options.includeInventoryReview,
        runAutopilot: options.runAutopilot,
        includeBrsrOrchestration: options.includeBrsrOrchestration,
        includeIsoOrchestration: options.includeIsoOrchestration,
        includePcfOrchestration: options.includePcfOrchestration,
        includeCbamOrchestration: options.includeCbamOrchestration,
        accumulated,
      });

      const data = (response as { data?: Record<string, unknown> })?.data || {};
      const stageFailed = (data.stages as Array<{ status?: string }> | undefined)?.some(
        (entry) => entry.status === 'failed'
      );

      accumulated = {
        workflowResult: data.workflow ?? accumulated.workflowResult,
        reportIndex: data.reportIndex ?? accumulated.reportIndex,
        reports: data.reports ?? accumulated.reports,
        stages: [
          ...((accumulated.stages as unknown[]) || []),
          ...((data.stages as unknown[]) || []),
        ],
        bundle: data.bundle ?? accumulated.bundle,
      };

      if (data.bundle && typeof data.bundle === 'object') {
        lastBundle = data.bundle as StagedReportOrchestrationResult['bundle'];
      }
      if (typeof data.message === 'string') {
        lastMessage = data.message;
      }
      if (Array.isArray(data.partialFailures)) {
        lastPartialFailures = [
          ...lastPartialFailures,
          ...data.partialFailures,
        ];
      }

      stageStates[index] = {
        ...stageStates[index],
        status: stageFailed ? 'failed' : 'completed',
        error: stageFailed
          ? (data.stages as Array<{ error?: string }> | undefined)?.find((entry) => entry.error)?.error
          : null,
      };
      options.onStageComplete?.(stage, data);

      if (stageFailed) {
        overallSuccess = false;
        break;
      }
    } catch (error) {
      overallSuccess = false;
      stageStates[index] = {
        ...stageStates[index],
        status: 'failed',
        error: error instanceof Error ? error.message : 'Stage failed',
      };
      break;
    }
  }

  return {
    success: overallSuccess,
    profile,
    stages: stageStates,
    bundle: lastBundle,
    partialFailures: lastPartialFailures,
    message: lastBundle?.summary?.message || lastMessage,
  };
}
