import React, { useCallback, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Stack,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import ApiService from '../../services/api';
import { getStoredSignupGoal } from '../../constants/signupGoals';

interface BuyerInboxItem {
  buyerName: string;
  frameworkLabel: string;
  urgency: string;
  daysToDue: number | null;
  dueDate?: string | null;
  readinessScore?: number;
  packReady?: boolean;
  missingPackFields?: string[];
  missingQuestionnaireFields?: string[];
  packHubLink?: string;
}

const urgencyColor = (urgency: string): 'error' | 'warning' | 'default' => {
  if (urgency === 'high' || urgency === 'overdue') return 'error';
  if (urgency === 'medium') return 'warning';
  return 'default';
};

/**
 * Buyer inbox is loaded on demand — auto-POST runMsmeAdvisory on Compliance mount
 * previously doubled AI advisory traffic alongside the Dashboard advisory query.
 */
const BuyerRequestInbox: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [inbox, setInbox] = useState<BuyerInboxItem[]>([]);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.runMsmeAdvisory({
        signupGoal: getStoredSignupGoal() || 'buyer_audit',
        period: 'annual',
      });
      const data = (res as { data?: { outputs?: { buyerAdvisory?: { inbox?: BuyerInboxItem[] } } } })?.data;
      setInbox(data?.outputs?.buyerAdvisory?.inbox || []);
      setLoaded(true);
    } catch (e) {
      setInbox([]);
      setLoaded(true);
      setError(e instanceof Error ? e.message : 'Could not load buyer request inbox');
    } finally {
      setLoading(false);
    }
  }, []);

  if (!loaded && !loading) {
    return (
      <Alert
        severity="info"
        action={
          <Button color="inherit" size="small" onClick={() => void load()}>
            Load inbox
          </Button>
        }
      >
        Buyer questionnaires load on demand to keep Compliance hub opening light.
      </Alert>
    );
  }

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 3 }}>
        <CircularProgress size={28} />
      </Box>
    );
  }

  if (error) {
    return (
      <Alert
        severity="warning"
        action={
          <Button color="inherit" size="small" onClick={() => void load()}>
            Retry
          </Button>
        }
      >
        {error}
      </Alert>
    );
  }

  if (inbox.length === 0) {
    return (
      <Alert severity="info">
        No open buyer questionnaires. When a customer sends a sustainability audit template, register it in
        Compliance hub supplier questionnaires.
      </Alert>
    );
  }

  return (
    <Stack spacing={2}>
      {inbox.map((item) => (
        <Card key={`${item.buyerName}-${item.dueDate || 'nodate'}`} variant="outlined">
          <CardContent>
            <Stack direction="row" justifyContent="space-between" alignItems="flex-start">
              <Box>
                <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
                  {item.buyerName}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  {item.frameworkLabel}
                </Typography>
                {item.daysToDue != null ? (
                  <Typography variant="caption" color="text.secondary">
                    {item.daysToDue < 0
                      ? `Overdue by ${Math.abs(item.daysToDue)} day(s)`
                      : `Due in ${item.daysToDue} day(s)`}
                  </Typography>
                ) : null}
              </Box>
              <Chip size="small" label={item.urgency} color={urgencyColor(item.urgency)} />
            </Stack>
            {item.missingPackFields && item.missingPackFields.length > 0 ? (
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                Missing pack fields:{' '}
                {[
                  ...item.missingPackFields,
                  ...(item.missingQuestionnaireFields || []),
                ].join(', ')}
              </Typography>
            ) : null}
            <Button
              component={RouterLink}
              to={item.packHubLink || '/buyer-audit'}
              size="small"
              sx={{ mt: 1.5 }}
            >
              Complete buyer pack
            </Button>
          </CardContent>
        </Card>
      ))}
    </Stack>
  );
};

export default BuyerRequestInbox;
