import React, { useMemo, useState } from 'react';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Stack,
  Step,
  StepLabel,
  Stepper,
  Typography,
} from '@mui/material';
import {
  ArrowForward as ArrowForwardIcon,
  AutoFixHigh as AutopilotIcon,
  CheckCircle as CheckCircleIcon,
  ExpandMore as ExpandMoreIcon,
  PlayArrow as PlayArrowIcon,
} from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import ApiService from '../../services/api';
import ReportGenerationStepper, { useStagedReportGeneration } from '../reporting/ReportGenerationStepper';
import ComplianceReadinessActionQueue, {
  type PrioritizedReadinessAction,
} from './ComplianceReadinessActionQueue';
import ComplianceReadinessGapPanel, { type ModuleGapBundle } from './ComplianceReadinessGapPanel';
import {
  MSME_READINESS_CHECKLIST_ALL_GAPS,
  MSME_READINESS_CHECKLIST_COMPLETE,
  MSME_READINESS_CHECKLIST_SUBTITLE,
} from '../../constants/msmeSimplifiedUi';
import {
  MSME_PREPARE_REPORTS_THRESHOLD,
  MSME_SIMPLIFIED_ACTION_LABELS,
} from '../../constants/msmeSimplifiedUi';
import { buildMsmeReadinessSteps } from '../../utils/buildMsmeReadinessSteps';
import { msmeProgressLabel } from '../../constants/reportingUxLabels';

type MsmeReadinessChecklistProps = {
  prioritizedActions: PrioritizedReadinessAction[];
  moduleGapDetails: Record<string, ModuleGapBundle>;
  moduleKeys: string[];
  overallReadinessScore?: number | null;
  period?: string;
  exportApplicable?: boolean;
  onRefresh?: () => void;
  showExpandedDetails?: boolean;
  layout?: 'hub' | 'embedded';
  /** When true, parent ComplianceOrchestrationHub owns primary readiness CTA. */
  hideOrchestrationControls?: boolean;
  /** Overview-only presentation. Other pages keep the previous checklist look. */
  overviewPresentation?: boolean;
  /** Marks the first remaining visible step active. Does not change completion. */
  emphasizeCurrentStep?: boolean;
  /** Outlined Open actions in the embedded gap queue. */
  emphasizeRowActions?: boolean;
  /** Outlined readiness-check and generate buttons in the embedded queue toolbar. */
  secondaryToolbarActions?: boolean;
  /** Drops the inner queue border when the checklist card already frames the list. */
  softenEmbeddedQueue?: boolean;
};

const MsmeReadinessChecklist: React.FC<MsmeReadinessChecklistProps> = ({
  prioritizedActions,
  moduleGapDetails,
  moduleKeys,
  overallReadinessScore = null,
  period = 'annual',
  exportApplicable = false,
  onRefresh,
  showExpandedDetails = true,
  layout = 'hub',
  hideOrchestrationControls = false,
  overviewPresentation = false,
  emphasizeCurrentStep = false,
  emphasizeRowActions = false,
  secondaryToolbarActions = false,
  softenEmbeddedQueue = false,
}) => {
  const [orchestrating, setOrchestrating] = useState(false);
  const [generatingAll, setGeneratingAll] = useState(false);
  const stagedGeneration = useStagedReportGeneration({ period, exportApplicable, profile: 'standard' });
  const [autopilotRunning, setAutopilotRunning] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const steps = useMemo(
    () => buildMsmeReadinessSteps({
      prioritizedActions,
      moduleGapDetails,
      moduleKeys,
      overallReadinessScore,
      maxSteps: 3,
      includeDefaultRecheck: !hideOrchestrationControls,
    }),
    [prioritizedActions, moduleGapDetails, moduleKeys, overallReadinessScore, hideOrchestrationControls]
  );

  const totalOpenGaps = useMemo(
    () => moduleKeys.reduce((sum, key) => sum + (moduleGapDetails[key]?.gapCount || 0), 0),
    [moduleGapDetails, moduleKeys]
  );

  const runReadinessCheck = async () => {
    setOrchestrating(true);
    setError(null);
    setFeedback(null);
    try {
      const res = await ApiService.orchestrateReportingReadiness({
        period,
        actionLimit: 8,
        runAutopilot: false,
        includeBrsrOrchestration: false,
        includeIsoOrchestration: false,
        includePcfOrchestration: exportApplicable,
        includeCbamOrchestration: exportApplicable,
      });
      const data = (res as { data?: { message?: string; overallReadinessScore?: number } })?.data;
      setFeedback(
        data?.message?.replace(/orchestration/gi, 'readiness check')
          || (data?.overallReadinessScore != null
            ? `Readiness check complete — overall ${Math.round(data.overallReadinessScore)}%.`
            : 'Readiness check complete.')
      );
      onRefresh?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Readiness check failed.');
    } finally {
      setOrchestrating(false);
    }
  };

  const runGenerateAllReports = async () => {
    setGeneratingAll(true);
    setError(null);
    setFeedback(null);
    try {
      const result = await stagedGeneration.runStandard();
      setFeedback(
        result.bundle?.summary?.message
          || `Generated ${result.bundle?.summary?.successCount ?? 0} report bundles.`
      );
      onRefresh?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Report generation failed.');
    } finally {
      setGeneratingAll(false);
    }
  };

  const runAutopilot = async () => {
    setAutopilotRunning(true);
    setError(null);
    setFeedback(null);
    try {
      const result = await ApiService.runComplianceHubAutopilot({
        period,
        applyChanges: true,
        runAgents: true,
      });
      const payload = (result as { data?: { closuresApplied?: unknown[]; documentVerifications?: unknown[] } })?.data;
      const closuresApplied = payload?.closuresApplied;
      const documentVerifications = payload?.documentVerifications;
      const closureCount = Array.isArray(closuresApplied) ? closuresApplied.length : 0;
      const docCount = Array.isArray(documentVerifications) ? documentVerifications.length : 0;
      setFeedback(
        closureCount || docCount
          ? `Auto-fix complete — ${docCount} document check(s), ${closureCount} update(s) applied.`
          : 'Auto-fix finished — no additional changes were needed.'
      );
      onRefresh?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Auto-fix failed.');
    } finally {
      setAutopilotRunning(false);
    }
  };

  const healthy = totalOpenGaps === 0;
  const canPrepareReports = (overallReadinessScore ?? 0) >= MSME_PREPARE_REPORTS_THRESHOLD;
  const checklistTitle = steps.length === 1
    ? 'Your next step'
    : steps.length > 1
      ? `Your ${steps.length} steps`
      : 'Your next steps';
  const activeStep = (overviewPresentation || emphasizeCurrentStep) && steps.length > 0 && steps[0].completed !== true
    ? 0
    : -1;

  return (
    <Card variant="outlined" sx={{ mb: 3 }}>
      <CardContent>
        <Stack spacing={2}>
          <Box>
            <Typography variant="h6" fontWeight={700} gutterBottom>
              {checklistTitle}
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 720 }}>
              {MSME_READINESS_CHECKLIST_SUBTITLE}
            </Typography>
            {overallReadinessScore != null ? (
              <Chip
                size="small"
                sx={{ mt: 1.5 }}
                label={msmeProgressLabel(overallReadinessScore)}
                color={overallReadinessScore >= 75 ? 'success' : 'warning'}
                variant="outlined"
              />
            ) : null}
          </Box>

          {feedback ? <Alert severity="success">{feedback}</Alert> : null}
          {error ? <Alert severity="error">{error}</Alert> : null}
          <ReportGenerationStepper
            running={generatingAll || stagedGeneration.running}
            stages={stagedGeneration.stages}
          />

          {healthy && steps.length === 0 ? (
            <Alert severity="success" icon={<CheckCircleIcon />}>
              {MSME_READINESS_CHECKLIST_COMPLETE}
            </Alert>
          ) : (
            <Stepper orientation="vertical" nonLinear activeStep={activeStep}>
              {steps.map((step) => (
                <Step key={step.id} completed={step.completed}>
                  <StepLabel
                    optional={(
                      <Stack spacing={1} sx={{ mt: 0.5, pb: 2, pl: { xs: 0, sm: 4 } }}>
                        {step.detail ? (
                          <Typography variant="body2" color="text.secondary">
                            {step.detail}
                          </Typography>
                        ) : null}
                        <Button
                          variant="contained"
                          size="small"
                          component={RouterLink}
                          to={step.hubLink}
                          endIcon={<ArrowForwardIcon />}
                        >
                          {step.ctaLabel}
                        </Button>
                      </Stack>
                    )}
                  >
                    <Typography variant="subtitle1" fontWeight={700}>
                      Step {step.stepNumber}: {step.title}
                    </Typography>
                  </StepLabel>
                </Step>
              ))}
            </Stepper>
          )}

          {hideOrchestrationControls ? (
            canPrepareReports ? (
              <Button
                variant="outlined"
                color="secondary"
                disabled={generatingAll || stagedGeneration.running}
                onClick={() => void runGenerateAllReports()}
                startIcon={(generatingAll || stagedGeneration.running) ? <CircularProgress size={16} color="inherit" /> : <PlayArrowIcon />}
              >
                {(generatingAll || stagedGeneration.running) ? 'Preparing…' : MSME_SIMPLIFIED_ACTION_LABELS.prepareAllReports}
              </Button>
            ) : null
          ) : (
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} flexWrap="wrap" useFlexGap alignItems="center">
              <Button
                variant="contained"
                size={layout === 'hub' ? 'large' : 'medium'}
                disabled={orchestrating}
                onClick={() => void runReadinessCheck()}
                startIcon={orchestrating ? <CircularProgress size={18} color="inherit" /> : <PlayArrowIcon />}
              >
                {orchestrating ? 'Checking…' : MSME_SIMPLIFIED_ACTION_LABELS.checkReadiness}
              </Button>
              {canPrepareReports ? (
                <Button
                  variant="outlined"
                  color="secondary"
                  disabled={generatingAll || stagedGeneration.running}
                  onClick={() => void runGenerateAllReports()}
                  startIcon={(generatingAll || stagedGeneration.running) ? <CircularProgress size={16} color="inherit" /> : <PlayArrowIcon />}
                >
                  {(generatingAll || stagedGeneration.running) ? 'Preparing…' : MSME_SIMPLIFIED_ACTION_LABELS.prepareAllReports}
                </Button>
              ) : null}
              {overviewPresentation || !canPrepareReports ? (
                <Button
                  variant="text"
                  size="small"
                  disabled={autopilotRunning}
                  onClick={() => void runAutopilot()}
                  startIcon={autopilotRunning ? <CircularProgress size={16} /> : <AutopilotIcon />}
                >
                  {autopilotRunning ? 'Matching…' : MSME_SIMPLIFIED_ACTION_LABELS.matchBills}
                </Button>
              ) : null}
            </Stack>
          )}

          {showExpandedDetails && (totalOpenGaps > 0 || prioritizedActions.length > steps.length) ? (
            <Accordion
              disableGutters
              elevation={0}
              sx={{ bgcolor: 'transparent', '&:before': { display: 'none' } }}
              TransitionProps={{ unmountOnExit: true }}
            >
              <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                <Typography variant="body2" fontWeight={600}>
                  {MSME_READINESS_CHECKLIST_ALL_GAPS}
                  {' '}
                  ({Math.max(totalOpenGaps, prioritizedActions.length)})
                </Typography>
              </AccordionSummary>
              <AccordionDetails sx={{ px: 0 }}>
                <ComplianceReadinessActionQueue
                  actions={prioritizedActions}
                  onRefresh={onRefresh}
                  period={period}
                  exportApplicable={exportApplicable}
                  layout="default"
                  overviewPresentation={overviewPresentation}
                  emphasizeRowActions={emphasizeRowActions}
                  secondaryToolbarActions={secondaryToolbarActions}
                  softenEmbeddedQueue={softenEmbeddedQueue}
                />
                <ComplianceReadinessGapPanel
                  moduleGapDetails={moduleGapDetails}
                  moduleKeys={moduleKeys}
                  simplified
                  period={period}
                  onResolved={onRefresh}
                  overviewPresentation={overviewPresentation}
                  emphasizeRowActions={emphasizeRowActions}
                />
              </AccordionDetails>
            </Accordion>
          ) : null}
        </Stack>
      </CardContent>
    </Card>
  );
};

export default MsmeReadinessChecklist;
